const input=$json.body??$json;
const text=v=>v===null||v===undefined?'':String(v).trim();
const bool=v=>typeof v==='boolean'?v:['true','1','yes','on'].includes(text(v).toLowerCase());

const exception_id=Number(input.exception_id);
const options_per_patient=Number(input.options_per_patient??3);
const search_days=Number(input.search_days??14);
const channel=text(input.channel||'whatsapp').toLowerCase();
const webhook_base_url=text(input.webhook_base_url||'http://localhost:5678/webhook').replace(/\/+$/,'');
const confirm_run=bool(input.confirm_run);
const errors=[];

if(!Number.isInteger(exception_id)||exception_id<1)errors.push({field:'exception_id',message:'شناسه تغییر تقویم معتبر نیست.'});
if(!Number.isInteger(options_per_patient)||options_per_patient<1||options_per_patient>5)errors.push({field:'options_per_patient',message:'تعداد گزینه‌ها باید بین 1 و 5 باشد.'});
if(!Number.isInteger(search_days)||search_days<1||search_days>60)errors.push({field:'search_days',message:'بازه جست‌وجو معتبر نیست.'});
if(!['whatsapp','sms','email','phone','web_push','in_app'].includes(channel))errors.push({field:'channel',message:'کانال معتبر نیست.'});
if(!/^https?:\/\/.+/i.test(webhook_base_url))errors.push({field:'webhook_base_url',message:'آدرس Webhook معتبر نیست.'});
if(confirm_run!==true)errors.push({field:'confirm_run',message:'اجرای فرایند باید تأیید شود.'});

return [{json:{
 exception_id,options_per_patient,search_days,channel,webhook_base_url,
 prepare_url:`${webhook_base_url}/clinic/schedule-exceptions/prepare-affected-cases`,
 queue_url:`${webhook_base_url}/clinic/communications/messages/queue`,
 confirm_run,validation_status:errors.length?'invalid':'valid',errors
}}];

const response=$json??{};
const cases=Array.isArray(response.disruption_cases)?response.disruption_cases:[];
const cfg=$('Normalize and Validate Disruption Messaging').first().json;

if(!cases.length){
  return [{json:{
    success:true,has_case:false,
    result:response.result||'no_affected_appointments',
    exception_id:cfg.exception_id,
    disruption_case_count:Number(response.disruption_case_count||0)
  }}];
}

return cases.map(item=>({json:{
  ...item,has_case:true,
  clinic_name:response.clinic_name||'',
  exception_id:cfg.exception_id,
  channel:cfg.channel,
  webhook_base_url:cfg.webhook_base_url,
  queue_url:cfg.queue_url
}}));

const item=$json;
const slots=Array.isArray(item.proposed_slots)?item.proposed_slots:[];
const slotLines=slots.slice(0,5).map((slot,index)=>{
  const date=slot.date||slot.target_date||slot.appointment_date||'';
  const start=slot.start_time||slot.starts_at||'';
  return `${index+1}) ${date} ${start}`.trim();
});

const message=[
  `به‌دلیل تغییر فوری در برنامه ${item.doctor_name}، نوبت قبلی شما نیازمند بازتنظیم است.`,
  `خدمت: ${item.service_name}`,
  `زمان قبلی: ${item.original_appointment_date} ساعت ${item.original_start_time}`,
  '',
  slotLines.length?'زمان‌های جایگزین پیشنهادی:':'در حال حاضر زمان جایگزین قطعی در دسترس نیست.',
  ...slotLines,
  '',
  'لطفاً انتخاب خود یا درخواست تماس با منشی را اعلام کنید.',
  `کد پرونده جابه‌جایی: ${item.disruption_case_id}`
].join('\n');

return [{json:{
  queue_url:item.queue_url,
  disruption_case_id:Number(item.disruption_case_id),
  appointment_id:Number(item.appointment_id),
  queue_payload:{
    clinic_name:item.clinic_name,
    mobile:item.mobile,
    channel:item.channel,
    purpose:'appointment_update',
    message_type:'interactive',
    template_code:'appointment_disruption_notice',
    language:'fa',
    subject:'',
    message_text:message,
    payload:{
      exception_id:item.exception_id,
      disruption_case_id:Number(item.disruption_case_id),
      appointment_id:Number(item.appointment_id),
      original_appointment_date:item.original_appointment_date,
      original_start_time:item.original_start_time,
      proposed_slots:slots,
      response_endpoint:'clinic/disruptions/process-patient-decision'
    },
    related_entity_type:'appointment',
    related_entity_id:Number(item.appointment_id),
    request_reference:`disruption-case:${item.disruption_case_id}`,
    idempotency_key:`disruption-case:${item.disruption_case_id}:initial-notice`,
    priority:8,
    scheduled_at:new Date().toISOString(),
    max_attempts:6,
    webhook_base_url:item.webhook_base_url,
    confirm_queue:true
  }
}}];

const original=$('Build Disruption Notification').item.json;
return [{json:{
  success:$json.success===true,
  result:$json.result||'queue_result_unknown',
  disruption_case_id:original.disruption_case_id,
  appointment_id:original.appointment_id,
  outbound_message_id:$json.outbound_message_id??null,
  message_status:$json.message_status??null,
  permission_decision:$json.permission_decision??null
}}];
